#include <bits/stdc++.h>
using namespace std;
struct HK{int L,R;vector<vector<int>>a;vector<int>ml,mr,d;HK(int L,int R):L(L),R(R),a(L),ml(L,-1),mr(R,-1),d(L){}bool bfs(){queue<int>q;bool ok=false;for(int u=0;u<L;u++){if(ml[u]<0)d[u]=0,q.push(u);else d[u]=-1;}while(!q.empty()){int u=q.front();q.pop();for(int v:a[u]){int w=mr[v];if(w<0)ok=true;else if(d[w]<0)d[w]=d[u]+1,q.push(w);}}return ok;}bool dfs(int u){for(int v:a[u]){int w=mr[v];if(w<0||(d[w]==d[u]+1&&dfs(w))){ml[u]=v;mr[v]=u;return true;}}d[u]=-1;return false;}int run(){int m=0;while(bfs())for(int u=0;u<L;u++)if(ml[u]<0&&dfs(u))m++;return m;}};
static int n,eidx,fidx,baseMask;static vector<pair<int,int>>E;
int idxedge(int x,int y){if(x>y)swap(x,y);for(int i=0;i<(int)E.size();i++)if(E[i]==make_pair(x,y))return i;return -1;}
bool forest(int m){int p[8];iota(p,p+n,0);function<int(int)>f=[&](int x){return p[x]==x?x:p[x]=f(p[x]);};for(int i=0;i<(int)E.size();i++)if(m>>i&1){auto [x,y]=E[i];x=f(x);y=f(y);if(x==y)return false;p[y]=x;}return true;}
void setup(int N,bool adjacent){n=N;E.clear();for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)E.push_back({i,j});eidx=idxedge(0,1);fidx=adjacent?idxedge(0,2):idxedge(2,3);baseMask=((1<<(int)E.size())-1)&~(1<<eidx)&~(1<<fidx);}
vector<int> path(int m){int s=E[eidx].first,t=E[eidx].second;vector<vector<pair<int,int>>>g(n);for(int i=0;i<(int)E.size();i++)if(m>>i&1){auto [x,y]=E[i];g[x].push_back({y,i});g[y].push_back({x,i});}vector<int>pv(n,-1),pe(n,-1);queue<int>q;q.push(s);pv[s]=s;while(!q.empty()){int x=q.front();q.pop();for(auto [y,z]:g[x])if(pv[y]<0)pv[y]=x,pe[y]=z,q.push(y);}vector<int>r;if(pv[t]<0)return r;for(int x=t;x!=s;x=pv[x])r.push_back(pe[x]);reverse(r.begin(),r.end());return r;}
vector<int> cuts(int F,int k){auto p=path(F);vector<int>o;if(k==1){for(int x:p)o.push_back(F&~(1<<x));}else for(int i=0;i<(int)p.size();i++)for(int j=i+1;j<(int)p.size();j++)o.push_back(F&~(1<<p[i])&~(1<<p[j]));sort(o.begin(),o.end());o.erase(unique(o.begin(),o.end()),o.end());return o;}
vector<int> adds(int H,int k){vector<int>v,o;for(int i=0;i<(int)E.size();i++)if(!(H>>i&1)&&i!=eidx&&i!=fidx)v.push_back(i);if(k==1){for(int x:v){int h=H|(1<<x);if(forest(h)&&forest(h|(1<<fidx))&&!forest(h|(1<<eidx)|(1<<fidx)))o.push_back(h);}}else for(int i=0;i<(int)v.size();i++)for(int j=i+1;j<(int)v.size();j++){int h=H|(1<<v[i])|(1<<v[j]);if(forest(h)&&forest(h|(1<<fidx))&&!forest(h|(1<<eidx)|(1<<fidx)))o.push_back(h);}sort(o.begin(),o.end());o.erase(unique(o.begin(),o.end()),o.end());return o;}
struct Counts{vector<int>N,A,B,D,Fbad,BmD;};
Counts counts(){Counts c;for(int H=baseMask;;H=(H-1)&baseMask){if(forest(H)){c.N.push_back(H);if(forest(H|(1<<eidx)))c.A.push_back(H);if(forest(H|(1<<fidx)))c.B.push_back(H);if(forest(H|(1<<eidx)|(1<<fidx)))c.D.push_back(H);}if(H==0)break;}unordered_set<int>A(c.A.begin(),c.A.end()),D(c.D.begin(),c.D.end());for(int x:c.N)if(!A.count(x))c.Fbad.push_back(x);for(int x:c.B)if(!D.count(x))c.BmD.push_back(x);return c;}
long long exact_match(int N,bool adj){setup(N,adj);auto c=counts();unordered_map<int,int>ia,ih;for(int i=0;i<(int)c.A.size();i++)ia[c.A[i]]=i;for(int i=0;i<(int)c.BmD.size();i++)ih[c.BmD[i]]=i;vector<array<vector<int>,2>>FX(c.Fbad.size()),HY(c.D.size());for(int i=0;i<(int)c.Fbad.size();i++)for(int k=1;k<=2;k++)for(int J:cuts(c.Fbad[i],k))if(ia.count(J))FX[i][k-1].push_back(ia[J]);for(int i=0;i<(int)c.D.size();i++)for(int k=1;k<=2;k++)for(int H:adds(c.D[i],k))if(ih.count(H))HY[i][k-1].push_back(ih[H]);long long L=(long long)c.Fbad.size()*c.D.size(),R=(long long)c.A.size()*c.BmD.size();HK hk((int)L,(int)R);long long ed=0;for(int i=0;i<(int)c.Fbad.size();i++)for(int j=0;j<(int)c.D.size();j++){int u=i*(int)c.D.size()+j;for(int k=0;k<2;k++)for(int x:FX[i][k])for(int y:HY[j][k])hk.a[u].push_back(x*(int)c.BmD.size()+y);sort(hk.a[u].begin(),hk.a[u].end());hk.a[u].erase(unique(hk.a[u].begin(),hk.a[u].end()),hk.a[u].end());ed+=hk.a[u].size();}int mm=hk.run();cout<<(adj?"adjacent":"disjoint")<<" K"<<N<<" N="<<c.N.size()<<" A="<<c.A.size()<<" D="<<c.D.size()<<" BminusD="<<c.BmD.size()<<" domain="<<L<<" codomain="<<R<<" radius2_edges="<<ed<<" matching="<<mm<<"\n";if(mm!=(int)L)exit(40+N);return ed;}
int main(){ios::sync_with_stdio(false);cout<<"FOREST_RADIUS2_HALL_EXACT_CHECK_V2\n";
setup(5,false);auto c=counts();int Hfix=1<<idxedge(0,4);set<int>X1,X2;for(int F:c.Fbad){for(int J:cuts(F,1))X1.insert(J);for(int J:cuts(F,2))X2.insert(J);}auto Y1=adds(Hfix,1),Y2=adds(Hfix,2);int ordinary=0,q=0;for(int H:Y2){bool ea=forest(H|(1<<eidx));if(ea)q++;else ordinary++;}
cout<<"K5_fixed_H_ax domain_fiber="<<c.Fbad.size()<<" one_cut_shadow="<<X1.size()<<" one_blocker_outputs="<<Y1.size()<<" one_switch_neighborhood="<<X1.size()*Y1.size()<<" deficiency="<<(long long)c.Fbad.size()-(long long)X1.size()*Y1.size()<<"\n";
cout<<"K5_fixed_H_ax two_cut_shadow="<<X2.size()<<" two_blocker_outputs="<<Y2.size()<<" split_ordinary="<<ordinary<<" split_Q="<<q<<" radius2_raw_layer_capacity="<<(long long)X1.size()*Y1.size()+(long long)X2.size()*Y2.size()<<"\n";
if(c.Fbad.size()!=70||X1.size()!=60||Y1.size()!=1||X2.size()!=34||Y2.size()!=14||ordinary!=10||q!=4)return 9;
for(int N=3;N<=6;N++) exact_match(N,true);for(int N=4;N<=6;N++) exact_match(N,false);cout<<"ALL_EXACT_ASSERTIONS_PASSED\n";}
